import{_ as a,c as r,o as i,ah as l}from"./chunks/framework.MgE-7MWY.js";const m=JSON.parse('{"title":"Uber Go Style Guide - Cheatsheet","description":"","frontmatter":{},"headers":[],"relativePath":"uber-guide.md","filePath":"uber-guide.md"}'),s={name:"uber-guide.md"};function t(n,e,o,c,d,h){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="uber-go-style-guide-cheatsheet" tabindex="-1">Uber Go Style Guide - Cheatsheet <a class="header-anchor" href="#uber-go-style-guide-cheatsheet" aria-label="Permalink to “Uber Go Style Guide - Cheatsheet”">​</a></h1><h2 id="_1-general" tabindex="-1">1. General <a class="header-anchor" href="#_1-general" aria-label="Permalink to “1. General”">​</a></h2><ul><li>Clear &gt; Clever. Consistency &gt; Personal.</li><li>Prefer readability over brevity.</li></ul><h2 id="_2-packages-imports" tabindex="-1">2. Packages &amp; Imports <a class="header-anchor" href="#_2-packages-imports" aria-label="Permalink to “2. Packages &amp; Imports”">​</a></h2><ul><li>Lowercase package names, no underscore/dash.</li><li>Avoid vague names (<code>util</code>, <code>common</code>).</li><li>Import groups: stdlib, external, internal.</li></ul><h2 id="_3-variables-constants" tabindex="-1">3. Variables &amp; Constants <a class="header-anchor" href="#_3-variables-constants" aria-label="Permalink to “3. Variables &amp; Constants”">​</a></h2><ul><li>Short names for small scope, descriptive for larger.</li><li>MixedCaps, not snake_case.</li><li>Use const for constants, group with iota when needed.</li></ul><h2 id="_4-error-handling" tabindex="-1">4. Error Handling <a class="header-anchor" href="#_4-error-handling" aria-label="Permalink to “4. Error Handling”">​</a></h2><ul><li>Don&#39;t panic for normal errors.</li><li>Error messages: lowercase, no period.</li><li>Use errors.Is / errors.As.</li><li>Wrap with fmt.Errorf(&quot;context: %w&quot;, err).</li></ul><h2 id="_5-concurrency" tabindex="-1">5. Concurrency <a class="header-anchor" href="#_5-concurrency" aria-label="Permalink to “5. Concurrency”">​</a></h2><ul><li>Avoid goroutine leaks → use context or stop channels.</li><li>Close channels in sender, not receiver.</li><li>Use buffered channels when appropriate.</li></ul><h2 id="_6-slices-maps" tabindex="-1">6. Slices &amp; Maps <a class="header-anchor" href="#_6-slices-maps" aria-label="Permalink to “6. Slices &amp; Maps”">​</a></h2><ul><li>Preallocate capacity with make([]T, 0, n).</li><li>Always check existence in maps (val, ok := m[key]).</li><li>Declare maps with make, not nil.</li></ul><h2 id="_7-structs-interfaces" tabindex="-1">7. Structs &amp; Interfaces <a class="header-anchor" href="#_7-structs-interfaces" aria-label="Permalink to “7. Structs &amp; Interfaces”">​</a></h2><ul><li>Export struct fields only if needed.</li><li>Keep interfaces small (1-2 methods).</li><li>Define interfaces at consumer side.</li></ul><h2 id="_8-functions" tabindex="-1">8. Functions <a class="header-anchor" href="#_8-functions" aria-label="Permalink to “8. Functions”">​</a></h2><ul><li>Avoid overusing named returns.</li><li>Use struct for multiple params of same type.</li><li>Function name should reflect side effects.</li></ul><h2 id="_9-testing" tabindex="-1">9. Testing <a class="header-anchor" href="#_9-testing" aria-label="Permalink to “9. Testing”">​</a></h2><ul><li>TestXxx naming.</li><li>Prefer table-driven tests.</li><li>Avoid global state.</li><li>Use t.Helper() for helpers.</li></ul><h2 id="_10-performance-safety" tabindex="-1">10. Performance &amp; Safety <a class="header-anchor" href="#_10-performance-safety" aria-label="Permalink to “10. Performance &amp; Safety”">​</a></h2><ul><li>Prefer immutability.</li><li>Avoid unnecessary allocations, use sync.Pool.</li><li>Always pass context.Context as first param in APIs.</li></ul>',21)])])}const p=a(s,[["render",t]]);export{m as __pageData,p as default};
